class Solution {
public:
    bool canMakeSubsequence(string str1, string str2) {
        int n = str1.size(), m = str2.size();
        int j = 0;
        for (int i = 0; i < n && j < m; i++) {
            char c = str1[i];
            char inc = (c == 'z') ? 'a' : (char)(c + 1);
            if (c == str2[j] || inc == str2[j]) {
                j++;
            }
        }
        return j == m;
    }
};
